import hashlib
import secrets
import string
import sqlite3

def generate_salt():
    return secrets.token_hex(32)

def hash_password(password, salt):
    return hashlib.sha256((password + salt).encode()).hexdigest()

def is_valid_username(username):
    return len(username) >= 3

def is_valid_password(password):
    if len(password) < 8:
        return False
    if not any(char in string.punctuation for char in password):
        return False
    return True

def register_user(username, password):
    if not is_valid_username(username):
        print("Benutzername muss mindestens 3 Zeichen lang sein.")
        return False
    if not is_valid_password(password):
        print("Passwort muss mindestens 8 Zeichen lang sein und mindestens ein Sonderzeichen enthalten.")
        return False

    salt = generate_salt()
    hashed_password = hash_password(password, salt)

    try:
        conn = sqlite3.connect('users.db')
        cursor = conn.cursor()
        cursor.execute('CREATE TABLE IF NOT EXISTS users (username TEXT UNIQUE, password_hash TEXT, salt TEXT)')
        cursor.execute('INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)', (username, hashed_password, salt))
        conn.commit()
        print("Benutzer erfolgreich registriert.")
        return True
    except sqlite3.IntegrityError:
        print("Benutzername existiert bereits.")
        return False
    finally:
        conn.close()

# Beispielaufruf
register_user("testuser", "securePass!123")
